LLMResponse(content='def kth(arr, k):
    if not arr:
        raise ValueError("Cannot select from an empty list.")
    if k < 0 or k >= len(arr):
        raise IndexError("k is out of bounds for the provided list.")

    pivot = arr[0]
    below = [x for x in arr if x < pivot]
    above = [x for x in arr if x > pivot]

    num_less = len(below)
    num_less_or_eq = len(arr) - len(above)

    if k < num_less:
        return kth(below, k)
    elif k >= num_less_or_eq:
        return kth(above, k - num_less_or_eq)
    else:
        return pivot

