def vowels_count(s):
    """Return the number of vowels in the string s."""
    if not s:
        return 0

    lower_s = s.lower()
    vowels = set("aeiou")
    count = sum(1 for char in lower_s if char in vowels)
    if lower_s.endswith("y"):
        count += 1
    return count


